-- ------------------------------------------------------------------------------
-- 8. Supabase Storage Bucket: 'media' (Public)
-- ------------------------------------------------------------------------------
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'media',
  'media',
  true,
  52428800, -- 50MB
  ARRAY['image/png', 'image/jpeg', 'image/jpg', 'image/webp', 'image/svg+xml']
)
ON CONFLICT (id) DO UPDATE SET 
  public = true,
  file_size_limit = 52428800;

-- Storage Policies for 'media' bucket
DO $$
BEGIN
    DROP POLICY IF EXISTS "Public Access Media Bucket" ON storage.objects;
    CREATE POLICY "Public Access Media Bucket" 
    ON storage.objects 
    FOR SELECT 
    USING (bucket_id = 'media');

    DROP POLICY IF EXISTS "Admin Upload Media Bucket" ON storage.objects;
    CREATE POLICY "Admin Upload Media Bucket" 
    ON storage.objects 
    FOR INSERT 
    TO authenticated 
    WITH CHECK (bucket_id = 'media');

    DROP POLICY IF EXISTS "Admin Update Media Bucket" ON storage.objects;
    CREATE POLICY "Admin Update Media Bucket" 
    ON storage.objects 
    FOR UPDATE 
    TO authenticated 
    USING (bucket_id = 'media');

    DROP POLICY IF EXISTS "Admin Delete Media Bucket" ON storage.objects;
    CREATE POLICY "Admin Delete Media Bucket" 
    ON storage.objects 
    FOR DELETE 
    TO authenticated 
    USING (bucket_id = 'media');
END $$;
